import type { LocalPortfolio } from './types';

interface EncryptedBackup {
  format: 'HAMS-ENCRYPTED-ASSET-LEDGER' | 'FRAIS-5-ENCRYPTED-PORTFOLIO';
  version: 1 | 2;
  kdf: { name: 'PBKDF2'; hash: 'SHA-256'; iterations: number; salt: string };
  cipher: { name: 'AES-GCM'; iv: string; data: string };
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = '';
  bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
  return btoa(binary);
}

function base64ToBytes(value: string): Uint8Array {
  return Uint8Array.from(atob(value), (character) => character.charCodeAt(0));
}

async function deriveKey(password: string, salt: Uint8Array, iterations: number): Promise<CryptoKey> {
  const material = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', hash: 'SHA-256', salt: salt as BufferSource, iterations },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

export async function encryptPortfolio(portfolio: LocalPortfolio, password: string): Promise<string> {
  if (password.length < 8) throw new Error('备份密码至少需要8个字符');
  const iterations = 250_000;
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKey(password, salt, iterations);
  const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, new TextEncoder().encode(JSON.stringify(portfolio)));
  const backup: EncryptedBackup = {
    format: 'HAMS-ENCRYPTED-ASSET-LEDGER', version: 2,
    kdf: { name: 'PBKDF2', hash: 'SHA-256', iterations, salt: bytesToBase64(salt) },
    cipher: { name: 'AES-GCM', iv: bytesToBase64(iv), data: bytesToBase64(new Uint8Array(encrypted)) },
  };
  return JSON.stringify(backup, null, 2);
}

export async function decryptPortfolio(contents: string, password: string): Promise<LocalPortfolio> {
  const backup = JSON.parse(contents) as EncryptedBackup;
  const supported = (backup.format === 'HAMS-ENCRYPTED-ASSET-LEDGER' && backup.version === 2)
    || (backup.format === 'FRAIS-5-ENCRYPTED-PORTFOLIO' && backup.version === 1);
  if (!supported) throw new Error('不是受支持的资产、HAMS或FRAIS历史加密备份');
  const key = await deriveKey(password, base64ToBytes(backup.kdf.salt), backup.kdf.iterations);
  try {
    const iv = base64ToBytes(backup.cipher.iv);
    const encrypted = base64ToBytes(backup.cipher.data);
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: iv as BufferSource },
      key,
      encrypted as BufferSource,
    );
    const portfolio = JSON.parse(new TextDecoder().decode(decrypted)) as LocalPortfolio;
    if (![1, 2, 3, 4, 5, 6].includes(portfolio.schemaVersion) || !portfolio.values) throw new Error('备份内容不完整');
    return portfolio;
  } catch {
    throw new Error('备份密码错误或文件已损坏');
  }
}
